  ('autonome', 'Forfait 1 — Autonome', 'Autonome', 12000, array['Accès aux six semaines','Vidéos et leçons','Exercices interactifs','Journal personnel','Objectifs','Suivi personnel non clinique','Plan final']::text[], null, 0),
