insert into public.programmes (slug, code, title, summary, category, public_intro, public_goal, benefits, library_categories, status, cover_hue, sort_order, measures, open_for_requests)
insert into public.articles (slug, title, category, excerpt, body, sections, retenir, references_list, related, read_minutes, cover_hue, etat, featured, featured_order, sort_order, sensitive, professional_review_required) values
  ('la-sante-mentale-c-est-aussi-notre-sante', 'La santé mentale, c’est aussi notre santé', 'Comprendre la santé mentale', 'La santé mentale concerne nos émotions, nos pensées, nos relations et notre capacité à traverser les difficultés. Elle ne se résume pas à l’absence de diagnostic. Une personne peut aller travailler et sourire tout en vivant une souffrance importante.', array['La santé mentale concerne nos émotions, nos pensées, nos relations et notre capacité à traverser les difficultés. Elle ne se résume pas à l’absence de diagnostic. Une personne peut aller travailler et sourire tout en vivant une souffrance importante.']::text[], '[{"h":"Une situation du quotidien","p":["Après une journée chargée à Abidjan, quelqu’un peut se sentir vidé sans trouver les mots pour l’expliquer. Ce ressenti mérite d’être accueilli plutôt que comparé aux difficultés d’autrui."]},{"h":"Un premier pas possible","p":["Essayez de vous demander : qu’est-ce qui me pèse, qu’est-ce qui me soutient et de quoi ai-je besoin cette semaine ? Noter quelques mots peut aider à clarifier votre vécu."]},{"h":"Quand chercher du soutien ?","p":["Lorsque la souffrance dure, s’intensifie ou gêne votre quotidien, un professionnel de santé peut vous aider à comprendre ce qui se passe."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['quand-faut-il-demander-de-l-aide','les-tcc-expliquees-simplement','sante-mentale-cinq-idees-recues-a-questionner']::text[], 1, 'forest', 'a_relire', false, null, 1, false, false),
  ('quand-faut-il-demander-de-l-aide', 'Quand faut-il demander de l’aide ?', 'Comprendre la santé mentale', 'Il n’existe pas de seuil de souffrance à atteindre pour mériter du soutien. La durée des difficultés, leur intensité et leurs effets sur le sommeil, le travail, les relations ou la sécurité sont des indices utiles.', array['Il n’existe pas de seuil de souffrance à atteindre pour mériter du soutien. La durée des difficultés, leur intensité et leurs effets sur le sommeil, le travail, les relations ou la sécurité sont des indices utiles.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne qui évite progressivement ses proches, dort très peu et n’arrive plus à accomplir ses tâches habituelles peut avoir besoin de plus qu’un conseil de repos."]},{"h":"Un premier pas possible","p":["Parlez à une personne de confiance et prenez rendez-vous avec un professionnel de santé qualifié. Préparez des exemples précis : depuis quand, à quelle fréquence et avec quelles conséquences ?"]},{"h":"Quand chercher du soutien ?","p":["En cas de danger immédiat ou de pensées suicidaires avec risque de passage à l’acte, recherchez une aide urgente sur place."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['la-sante-mentale-c-est-aussi-notre-sante','les-tcc-expliquees-simplement','sante-mentale-cinq-idees-recues-a-questionner']::text[], 1, 'gold', 'a_relire', false, null, 2, true, true),
  ('les-tcc-expliquees-simplement', 'Les TCC, expliquées simplement', 'Comprendre la santé mentale', 'Les thérapies cognitives et comportementales, ou TCC, étudient les liens entre une situation, les pensées, les émotions, les sensations corporelles et les comportements. Elles proposent des expériences et des exercices concrets.', array['Les thérapies cognitives et comportementales, ou TCC, étudient les liens entre une situation, les pensées, les émotions, les sensations corporelles et les comportements. Elles proposent des expériences et des exercices concrets.']::text[], '[{"h":"Une situation du quotidien","p":["Avant un entretien, la pensée « Je vais forcément échouer » peut amplifier la peur et pousser à annuler. Éviter soulage sur le moment, mais peut entretenir l’appréhension."]},{"h":"Un premier pas possible","p":["Observez une situation récente sans vous juger : que s’est-il passé, qu’avez-vous pensé, ressenti et fait ? L’objectif n’est pas de penser positivement à tout prix, mais de trouver une réponse plus utile."]},{"h":"Quand chercher du soutien ?","p":["Un article de psychoéducation ne remplace pas une thérapie structurée ni une évaluation individuelle."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['la-sante-mentale-c-est-aussi-notre-sante','quand-faut-il-demander-de-l-aide','sante-mentale-cinq-idees-recues-a-questionner']::text[], 1, 'sage', 'a_relire', false, null, 3, false, false),
  ('sante-mentale-cinq-idees-recues-a-questionner', 'Santé mentale : cinq idées reçues à questionner', 'Comprendre la santé mentale', '« Les personnes fortes ne dépriment pas », « l’anxiété est un caprice » ou « demander de l’aide signifie être faible » : ces affirmations peuvent isoler celles et ceux qui souffrent. Les difficultés psychologiques ne disent rien de la valeur d’une personne.', array['« Les personnes fortes ne dépriment pas », « l’anxiété est un caprice » ou « demander de l’aide signifie être faible » : ces affirmations peuvent isoler celles et ceux qui souffrent. Les difficultés psychologiques ne disent rien de la valeur d’une personne.']::text[], '[{"h":"Une situation du quotidien","p":["Un proche peut sembler très organisé, assumer de nombreuses responsabilités et pourtant traverser une période de détresse."]},{"h":"Un premier pas possible","p":["Remplacez les jugements par des questions : « Comment te sens-tu vraiment ? », « Qu’est-ce qui est difficile ? », « Souhaites-tu que je t’accompagne pour demander de l’aide ? »"]},{"h":"Quand chercher du soutien ?","p":["Les symptômes persistants ou inhabituels méritent une évaluation adaptée, même si la personne semble « tenir bon »."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['la-sante-mentale-c-est-aussi-notre-sante','quand-faut-il-demander-de-l-aide','les-tcc-expliquees-simplement']::text[], 1, 'forest', 'a_relire', false, null, 4, false, false),
  ('depression-ou-simple-coup-de-blues', 'Dépression ou simple coup de blues ?', 'Dépression et humeur', 'La tristesse est une émotion humaine. La dépression peut s’accompagner d’une humeur basse persistante, d’une perte d’intérêt, de fatigue, de difficultés de concentration, de changements de sommeil ou d’appétit et d’un sentiment de désespoir. Tous les symptômes ne sont pas présents chez chacun.', array['La tristesse est une émotion humaine. La dépression peut s’accompagner d’une humeur basse persistante, d’une perte d’intérêt, de fatigue, de difficultés de concentration, de changements de sommeil ou d’appétit et d’un sentiment de désespoir. Tous les symptômes ne sont pas présents chez chacun.']::text[], '[{"h":"Une situation du quotidien","p":["Quelqu’un peut continuer à sourire en public tout en n’éprouvant plus de plaisir dans des activités autrefois appréciées."]},{"h":"Un premier pas possible","p":["Notez depuis quand les changements sont apparus et comment ils affectent votre quotidien. Une petite activité agréable ou utile peut être un premier pas, sans obligation de « se secouer »."]},{"h":"Quand chercher du soutien ?","p":["Consultez un professionnel de santé si ces difficultés persistent ou s’aggravent ; toute idée suicidaire nécessite une attention immédiate."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['quand-l-envie-de-faire-disparait','la-depression-chez-les-hommes-sortir-du-silence','la-depression-chez-l-adolescent']::text[], 1, 'gold', 'a_relire', true, 2, 5, true, true),
  ('quand-l-envie-de-faire-disparait', 'Quand l’envie de faire disparaît', 'Dépression et humeur', 'Lorsque le moral baisse, les activités deviennent difficiles. On se retire, on fait moins de choses satisfaisantes, puis l’humeur peut encore baisser : c’est un cercle qui peut s’installer.', array['Lorsque le moral baisse, les activités deviennent difficiles. On se retire, on fait moins de choses satisfaisantes, puis l’humeur peut encore baisser : c’est un cercle qui peut s’installer.']::text[], '[{"h":"Une situation du quotidien","p":["Awa remet sans cesse à plus tard un appel à une amie. Plus les jours passent, plus reprendre contact lui semble insurmontable."]},{"h":"Un premier pas possible","p":["Choisissez une action très petite, réalisable aujourd’hui : ouvrir la fenêtre, marcher cinq minutes, envoyer un message. Observez votre humeur avant et après, sans attendre une transformation immédiate."]},{"h":"Quand chercher du soutien ?","p":["Si vous n’arrivez plus à répondre à vos besoins essentiels, recherchez un soutien professionnel rapidement."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['depression-ou-simple-coup-de-blues','la-depression-chez-les-hommes-sortir-du-silence','la-depression-chez-l-adolescent']::text[], 1, 'sage', 'a_relire', false, null, 6, true, false),
  ('la-depression-chez-les-hommes-sortir-du-silence', 'La dépression chez les hommes : sortir du silence', 'Dépression et humeur', 'La dépression ne s’exprime pas toujours par des pleurs. Certaines personnes rapportent irritabilité, retrait, surinvestissement professionnel, fatigue ou consommation accrue d’alcool. Les attentes sociales autour de la masculinité peuvent rendre la demande d’aide plus difficile.', array['La dépression ne s’exprime pas toujours par des pleurs. Certaines personnes rapportent irritabilité, retrait, surinvestissement professionnel, fatigue ou consommation accrue d’alcool. Les attentes sociales autour de la masculinité peuvent rendre la demande d’aide plus difficile.']::text[], '[{"h":"Une situation du quotidien","p":["Un père peut dire « Je suis seulement fatigué » alors qu’il se sent vide et ne trouve plus de plaisir à rien."]},{"h":"Un premier pas possible","p":["Demandez sans accusation : « Comment ça se passe pour toi ces derniers temps ? » Évitez de réduire la souffrance à un manque de courage."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation de santé est utile lorsque les changements durent, affectent la vie quotidienne ou s’accompagnent d’idées noires."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['depression-ou-simple-coup-de-blues','quand-l-envie-de-faire-disparait','la-depression-chez-l-adolescent']::text[], 1, 'forest', 'a_relire', false, null, 7, true, false),
  ('la-depression-chez-l-adolescent', 'La dépression chez l’adolescent', 'Dépression et humeur', 'Chez les adolescents, la dépression peut se manifester par une tristesse persistante, mais aussi par de l’irritabilité, un isolement, une perte d’intérêt ou des difficultés scolaires. Une période de changements n’explique pas automatiquement toute souffrance.', array['Chez les adolescents, la dépression peut se manifester par une tristesse persistante, mais aussi par de l’irritabilité, un isolement, une perte d’intérêt ou des difficultés scolaires. Une période de changements n’explique pas automatiquement toute souffrance.']::text[], '[{"h":"Une situation du quotidien","p":["Un jeune qui abandonne soudain ses loisirs et évite ses amis n’est pas nécessairement « paresseux »."]},{"h":"Un premier pas possible","p":["Écoutez sans interrogatoire, prenez au sérieux ce qu’il raconte et demandez comment il se sent en sécurité. Associez des adultes protecteurs et des professionnels qualifiés."]},{"h":"Quand chercher du soutien ?","p":["Les propos suicidaires, l’automutilation ou une détérioration importante nécessitent une aide rapide et adaptée à l’âge."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['depression-ou-simple-coup-de-blues','quand-l-envie-de-faire-disparait','la-depression-chez-les-hommes-sortir-du-silence']::text[], 1, 'gold', 'a_relire', false, null, 8, true, true),
  ('aider-une-personne-qui-traverse-une-depression', 'Aider une personne qui traverse une dépression', 'Dépression et humeur', 'Soutenir ne signifie pas réparer l’autre. Une présence régulière, une écoute respectueuse et une aide concrète peuvent compter davantage que des injonctions à être positif.', array['Soutenir ne signifie pas réparer l’autre. Une présence régulière, une écoute respectueuse et une aide concrète peuvent compter davantage que des injonctions à être positif.']::text[], '[{"h":"Une situation du quotidien","p":["« Tu as tout pour être heureux » peut fermer la conversation, même lorsque l’intention est bonne."]},{"h":"Un premier pas possible","p":["Proposez une aide précise : accompagner à un rendez-vous, préparer un repas, marcher ensemble. Demandez ce qui serait réellement utile et respectez les limites de la personne."]},{"h":"Quand chercher du soutien ?","p":["Si la sécurité de la personne vous inquiète, ne restez pas seul avec cette responsabilité : sollicitez des professionnels ou les services d’urgence."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['depression-ou-simple-coup-de-blues','quand-l-envie-de-faire-disparait','la-depression-chez-les-hommes-sortir-du-silence']::text[], 1, 'sage', 'a_relire', false, null, 9, true, false),
  ('l-anxiete-quand-l-alarme-reste-allumee', 'L’anxiété : quand l’alarme reste allumée', 'Anxiété et peurs', 'L’anxiété est une réaction de protection. Elle devient problématique lorsqu’elle se déclenche souvent, paraît disproportionnée ou limite les activités. Elle peut se manifester par des pensées inquiétantes, une tension musculaire, des palpitations ou un besoin de vérifier.', array['L’anxiété est une réaction de protection. Elle devient problématique lorsqu’elle se déclenche souvent, paraît disproportionnée ou limite les activités. Elle peut se manifester par des pensées inquiétantes, une tension musculaire, des palpitations ou un besoin de vérifier.']::text[], '[{"h":"Une situation du quotidien","p":["Avant une réunion, une personne imagine de multiples catastrophes et vérifie son téléphone toutes les deux minutes."]},{"h":"Un premier pas possible","p":["Repérez le déclencheur, ce que votre esprit prédit et ce que vous faites pour vous rassurer. Essayez un ancrage sensoriel simple : nommer cinq choses visibles autour de vous."]},{"h":"Quand chercher du soutien ?","p":["Des symptômes physiques nouveaux, intenses ou inhabituels nécessitent une évaluation médicale ; une anxiété invalidante mérite un soutien professionnel."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe','trouble-panique-la-peur-d-avoir-peur']::text[], 1, 'forest', 'a_relire', true, 3, 10, true, false),
  ('anxiete-generalisee-l-esprit-qui-anticipe-tout', 'Anxiété généralisée : l’esprit qui anticipe tout', 'Anxiété et peurs', 'Lorsque les inquiétudes touchent de nombreux domaines et semblent difficiles à contrôler, elles peuvent épuiser. Le souci peut porter sur l’argent, la famille, la santé ou le travail, même en l’absence de problème immédiat.', array['Lorsque les inquiétudes touchent de nombreux domaines et semblent difficiles à contrôler, elles peuvent épuiser. Le souci peut porter sur l’argent, la famille, la santé ou le travail, même en l’absence de problème immédiat.']::text[], '[{"h":"Une situation du quotidien","p":["Une mère passe de la scolarité des enfants aux factures, puis à un éventuel accident, sans trouver de répit."]},{"h":"Un premier pas possible","p":["Distinguez une difficulté actuelle sur laquelle agir d’une hypothèse qui commence par « Et si... ? ». Pour les problèmes réels, cherchez une petite étape concrète ; pour les hypothèses répétitives, entraînez-vous à reporter la rumination."]},{"h":"Quand chercher du soutien ?","p":["Un professionnel peut évaluer si les inquiétudes correspondent à un trouble anxieux et proposer une prise en charge adaptée."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','attaque-de-panique-comprendre-ce-qui-se-passe','trouble-panique-la-peur-d-avoir-peur']::text[], 1, 'gold', 'a_relire', false, null, 11, true, false),
  ('attaque-de-panique-comprendre-ce-qui-se-passe', 'Attaque de panique : comprendre ce qui se passe', 'Anxiété et peurs', 'Une attaque de panique est une montée intense de peur ou de malaise, avec parfois cœur qui bat vite, souffle court, tremblements, vertiges ou impression de perdre le contrôle. L’expérience est très impressionnante, même si elle n’est pas toujours dangereuse.', array['Une attaque de panique est une montée intense de peur ou de malaise, avec parfois cœur qui bat vite, souffle court, tremblements, vertiges ou impression de perdre le contrôle. L’expérience est très impressionnante, même si elle n’est pas toujours dangereuse.']::text[], '[{"h":"Une situation du quotidien","p":["Dans un taxi, une personne sent son cœur accélérer et pense qu’elle va s’évanouir. Cette interprétation peut amplifier sa peur."]},{"h":"Un premier pas possible","p":["Si une évaluation médicale a écarté une urgence, ralentissez sans forcer votre respiration, sentez vos pieds au sol et nommez ce qui vous entoure. Évitez de vous reprocher la réaction de votre corps."]},{"h":"Quand chercher du soutien ?","p":["Une première crise, une douleur thoracique, un malaise ou des symptômes inhabituels doivent être évalués médicalement en urgence selon le contexte."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','trouble-panique-la-peur-d-avoir-peur']::text[], 1, 'sage', 'a_relire', false, null, 12, true, false),
  ('trouble-panique-la-peur-d-avoir-peur', 'Trouble panique : la peur d’avoir peur', 'Anxiété et peurs', 'Après des attaques de panique, certaines personnes se mettent à redouter la prochaine crise. Elles surveillent leur corps et évitent des situations, ce qui peut renforcer la peur.', array['Après des attaques de panique, certaines personnes se mettent à redouter la prochaine crise. Elles surveillent leur corps et évitent des situations, ce qui peut renforcer la peur.']::text[], '[{"h":"Une situation du quotidien","p":["Quelqu’un refuse les transports parce qu’il craint de ressentir à nouveau des palpitations devant les autres."]},{"h":"Un premier pas possible","p":["Repérez les anticipations et les évitements sans vous imposer de confrontation brutale. Des interventions TCC adaptées travaillent sur les interprétations des sensations et les comportements qui entretiennent le cercle."]},{"h":"Quand chercher du soutien ?","p":["Le diagnostic et le choix d’exercices d’exposition relèvent d’une évaluation professionnelle, surtout si des symptômes médicaux coexistent."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'forest', 'a_relire', false, null, 13, true, false),
  ('agoraphobie-quand-certains-lieux-deviennent-difficiles', 'Agoraphobie : quand certains lieux deviennent difficiles', 'Anxiété et peurs', 'L’agoraphobie concerne la peur de situations où s’échapper ou recevoir de l’aide semblerait difficile, par exemple transports, foules, files d’attente ou espaces ouverts. Ce n’est pas simplement « avoir peur de sortir ».', array['L’agoraphobie concerne la peur de situations où s’échapper ou recevoir de l’aide semblerait difficile, par exemple transports, foules, files d’attente ou espaces ouverts. Ce n’est pas simplement « avoir peur de sortir ».']::text[], '[{"h":"Une situation du quotidien","p":["Une personne commence par éviter un marché bondé, puis les trajets seuls, puis des déplacements ordinaires."]},{"h":"Un premier pas possible","p":["Accueillez la difficulté sans moquerie. Avec un professionnel si nécessaire, on peut envisager des étapes graduelles, choisies et adaptées à la sécurité réelle des lieux."]},{"h":"Quand chercher du soutien ?","p":["Une peur qui réduit fortement les déplacements ou l’autonomie justifie une consultation ; il ne faut jamais imposer une exposition dangereuse."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'gold', 'a_relire', false, null, 14, true, false),
  ('anxiete-sociale-le-regard-des-autres', 'Anxiété sociale : le regard des autres', 'Anxiété et peurs', 'L’anxiété sociale ne se réduit pas à la timidité. Elle implique une peur marquée d’être jugé, humilié ou rejeté, pouvant conduire à éviter de parler, manger ou participer devant d’autres.', array['L’anxiété sociale ne se réduit pas à la timidité. Elle implique une peur marquée d’être jugé, humilié ou rejeté, pouvant conduire à éviter de parler, manger ou participer devant d’autres.']::text[], '[{"h":"Une situation du quotidien","p":["Un étudiant connaît sa réponse, mais garde le silence de peur que sa voix tremble."]},{"h":"Un premier pas possible","p":["Essayez de repérer votre prédiction : « Ils vont tous se moquer ». Demandez-vous quelles preuves vous avez, puis choisissez une petite action réaliste qui respecte votre rythme."]},{"h":"Quand chercher du soutien ?","p":["Si l’évitement compromet les études, le travail ou les relations, une évaluation et une TCC adaptée peuvent aider."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'sage', 'a_relire', false, null, 15, true, false),
  ('phobies-specifiques-une-peur-qui-prend-trop-de-place', 'Phobies spécifiques : une peur qui prend trop de place', 'Anxiété et peurs', 'Une phobie spécifique correspond à une peur intense d’un objet ou d’une situation particulière : animal, hauteur, avion, injection, etc. L’évitement apporte un soulagement immédiat mais peut maintenir la peur.', array['Une phobie spécifique correspond à une peur intense d’un objet ou d’une situation particulière : animal, hauteur, avion, injection, etc. L’évitement apporte un soulagement immédiat mais peut maintenir la peur.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne renonce à un rendez-vous médical par peur des aiguilles."]},{"h":"Un premier pas possible","p":["Il peut être utile de comprendre ce que l’on redoute exactement. Une exposition graduée se prépare avec des étapes sûres, jamais en forçant ni en ignorant un danger réel."]},{"h":"Quand chercher du soutien ?","p":["Pour les phobies liées aux soins, parlez-en aux soignants ; certaines situations exigent des adaptations médicales spécifiques."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'forest', 'a_relire', false, null, 16, true, false),
  ('anxiete-de-separation-chez-l-enfant', 'Anxiété de séparation chez l’enfant', 'Anxiété et peurs', 'Il est normal qu’un enfant recherche la proximité de ses figures d’attachement. L’anxiété de séparation devient préoccupante si la peur est intense, durable, inadaptée à son développement et empêche les activités habituelles.', array['Il est normal qu’un enfant recherche la proximité de ses figures d’attachement. L’anxiété de séparation devient préoccupante si la peur est intense, durable, inadaptée à son développement et empêche les activités habituelles.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant se plaint chaque matin du ventre avant l’école et craint qu’un parent ne revienne pas."]},{"h":"Un premier pas possible","p":["Validez l’émotion, gardez des routines prévisibles et collaborez avec l’école. Évitez les promesses irréalistes comme « Rien de mauvais n’arrivera jamais »."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation pédiatrique et psychologique est utile si les symptômes persistent ou s’accompagnent de douleurs, d’absences scolaires ou d’autres difficultés."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'gold', 'a_relire', false, null, 17, true, true),
  ('l-anxiete-chez-les-enfants-ce-qu-ils-ne-savent-pas-toujours-dire', 'L’anxiété chez les enfants : ce qu’ils ne savent pas toujours dire', 'Anxiété et peurs', 'Les enfants n’expriment pas toujours leur anxiété avec des mots. Elle peut apparaître sous forme de maux de ventre, irritabilité, pleurs, évitement, questions répétitives ou besoin excessif d’être rassurés.', array['Les enfants n’expriment pas toujours leur anxiété avec des mots. Elle peut apparaître sous forme de maux de ventre, irritabilité, pleurs, évitement, questions répétitives ou besoin excessif d’être rassurés.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant demande dix fois si ses parents viendront le chercher, même après avoir reçu une réponse."]},{"h":"Un premier pas possible","p":["Utilisez des mots simples : « Ton corps te dit qu’il a peur ». Dessinez les émotions, cherchez ensemble ce qui inquiète et maintenez des repères rassurants sans renforcer tous les évitements."]},{"h":"Quand chercher du soutien ?","p":["Consultez si les symptômes perturbent durablement l’école, le sommeil, les relations ou le bien-être familial."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['l-anxiete-quand-l-alarme-reste-allumee','anxiete-generalisee-l-esprit-qui-anticipe-tout','attaque-de-panique-comprendre-ce-qui-se-passe']::text[], 1, 'sage', 'a_relire', false, null, 18, true, true),
  ('toc-bien-plus-que-vouloir-tout-ranger', 'TOC : bien plus que vouloir tout ranger', 'TOC et pensées intrusives', 'Le trouble obsessionnel-compulsif implique des obsessions, pensées ou images intrusives pénibles, et des compulsions, gestes ou actes mentaux visant à diminuer l’angoisse. Le TOC ne se résume pas à aimer la propreté ou l’ordre.', array['Le trouble obsessionnel-compulsif implique des obsessions, pensées ou images intrusives pénibles, et des compulsions, gestes ou actes mentaux visant à diminuer l’angoisse. Le TOC ne se résume pas à aimer la propreté ou l’ordre.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne vérifie sa porte à répétition, non par plaisir, mais parce qu’une inquiétude persistante l’empêche de partir."]},{"h":"Un premier pas possible","p":["Évitez de ridiculiser les rituels. Comprendre le cycle obsession--angoisse--compulsion est une première étape ; les traitements spécialisés peuvent inclure la TCC avec exposition et prévention de la réponse."]},{"h":"Quand chercher du soutien ?","p":["Un professionnel formé aux TOC peut proposer une évaluation et un plan adapté ; les exercices d’exposition ne doivent pas être improvisés pour des situations complexes."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['pensees-intrusives-penser-n-est-pas-vouloir','toc-pourquoi-les-rituels-entretiennent-ils-la-peur','toc-chez-l-enfant-reperer-sans-punir']::text[], 1, 'forest', 'a_relire', false, null, 19, true, false),
  ('pensees-intrusives-penser-n-est-pas-vouloir', 'Pensées intrusives : penser n’est pas vouloir', 'TOC et pensées intrusives', 'Il arrive que des pensées, images ou impulsions non désirées surgissent à l’esprit. Leur contenu peut être choquant et contraire aux valeurs de la personne. Avoir une pensée intrusive ne signifie pas vouloir la réaliser.', array['Il arrive que des pensées, images ou impulsions non désirées surgissent à l’esprit. Leur contenu peut être choquant et contraire aux valeurs de la personne. Avoir une pensée intrusive ne signifie pas vouloir la réaliser.']::text[], '[{"h":"Une situation du quotidien","p":["Une mère est bouleversée par une image soudaine de danger concernant son bébé et en conclut qu’elle est une mauvaise mère."]},{"h":"Un premier pas possible","p":["Essayez de nommer l’expérience : « C’est une pensée intrusive ». Évitez de chercher sans cesse une certitude absolue sur sa signification. Une aide spécialisée peut distinguer ces pensées d’autres situations cliniques."]},{"h":"Quand chercher du soutien ?","p":["Si vous craignez réellement de perdre le contrôle, présentez des symptômes psychotiques ou êtes en danger, demandez une évaluation urgente."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['toc-bien-plus-que-vouloir-tout-ranger','toc-pourquoi-les-rituels-entretiennent-ils-la-peur','toc-chez-l-enfant-reperer-sans-punir']::text[], 1, 'gold', 'a_relire', false, null, 20, true, false),
  ('toc-pourquoi-les-rituels-entretiennent-ils-la-peur', 'TOC : pourquoi les rituels entretiennent-ils la peur ?', 'TOC et pensées intrusives', 'Une compulsion peut procurer un apaisement rapide. Mais si le cerveau apprend qu’il faut répéter le rituel pour se sentir en sécurité, le besoin peut revenir de plus en plus souvent.', array['Une compulsion peut procurer un apaisement rapide. Mais si le cerveau apprend qu’il faut répéter le rituel pour se sentir en sécurité, le besoin peut revenir de plus en plus souvent.']::text[], '[{"h":"Une situation du quotidien","p":["Après avoir vérifié le gaz, une personne revient cinq fois chez elle. Chaque vérification la rassure quelques minutes."]},{"h":"Un premier pas possible","p":["Notez, sans jugement, le déclencheur, l’obsession, le rituel et le soulagement obtenu. Ce repérage aide à expliquer le cercle sans demander d’arrêter brutalement les comportements."]},{"h":"Quand chercher du soutien ?","p":["Un accompagnement spécialisé est recommandé lorsque les rituels prennent du temps ou entraînent une détresse importante."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['toc-bien-plus-que-vouloir-tout-ranger','pensees-intrusives-penser-n-est-pas-vouloir','toc-chez-l-enfant-reperer-sans-punir']::text[], 1, 'sage', 'a_relire', false, null, 21, true, false),
  ('toc-chez-l-enfant-reperer-sans-punir', 'TOC chez l’enfant : repérer sans punir', 'TOC et pensées intrusives', 'Un enfant peut répéter des gestes, poser les mêmes questions ou suivre des règles très strictes pour soulager une peur. Il peut avoir honte ou ne pas savoir expliquer ce qu’il ressent.', array['Un enfant peut répéter des gestes, poser les mêmes questions ou suivre des règles très strictes pour soulager une peur. Il peut avoir honte ou ne pas savoir expliquer ce qu’il ressent.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant recommence son devoir parce qu’il a peur qu’un malheur arrive s’il ne le fait pas « parfaitement »."]},{"h":"Un premier pas possible","p":["Écoutez avec calme, évitez les sanctions liées aux symptômes et demandez une évaluation adaptée à l’âge. Les proches peuvent apprendre à soutenir sans participer systématiquement aux rituels."]},{"h":"Quand chercher du soutien ?","p":["La prise en charge des TOC de l’enfant nécessite des professionnels formés et une collaboration avec la famille."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['toc-bien-plus-que-vouloir-tout-ranger','pensees-intrusives-penser-n-est-pas-vouloir','toc-pourquoi-les-rituels-entretiennent-ils-la-peur']::text[], 1, 'forest', 'a_relire', false, null, 22, true, true),
  ('stress-quand-le-corps-reste-en-alerte', 'Stress : quand le corps reste en alerte', 'Stress et épuisement', 'Le stress apparaît lorsque les exigences semblent dépasser nos ressources. À court terme, il peut mobiliser ; lorsqu’il persiste, il peut affecter le sommeil, l’attention, l’humeur et le corps.', array['Le stress apparaît lorsque les exigences semblent dépasser nos ressources. À court terme, il peut mobiliser ; lorsqu’il persiste, il peut affecter le sommeil, l’attention, l’humeur et le corps.']::text[], '[{"h":"Une situation du quotidien","p":["Entre les embouteillages, les dépenses et les obligations familiales, une journée ordinaire peut ressembler à une succession d’urgences."]},{"h":"Un premier pas possible","p":["Séparez ce qui est modifiable de ce qui ne l’est pas aujourd’hui. Identifiez une priorité, une pause réelle et une demande d’aide possible. Une respiration douce peut soutenir le retour au calme sans résoudre à elle seule les problèmes."]},{"h":"Quand chercher du soutien ?","p":["Des symptômes persistants, un épuisement majeur ou des douleurs physiques nécessitent une évaluation appropriée."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['surcharge-mentale-porter-l-invisible','burnout-comprendre-l-epuisement-professionnel','le-stress-au-travail-n-est-pas-toujours-individuel']::text[], 1, 'gold', 'a_relire', false, null, 23, false, false),
  ('surcharge-mentale-porter-l-invisible', 'Surcharge mentale : porter l’invisible', 'Stress et épuisement', 'La charge mentale inclut le travail de prévoir, organiser, se souvenir et anticiper. Elle peut être importante même lorsque les tâches visibles semblent partagées.', array['La charge mentale inclut le travail de prévoir, organiser, se souvenir et anticiper. Elle peut être importante même lorsque les tâches visibles semblent partagées.']::text[], '[{"h":"Une situation du quotidien","p":["Dans une famille, une personne connaît seule les rendez-vous, les fournitures scolaires et les échéances, même si d’autres participent aux tâches."]},{"h":"Un premier pas possible","p":["Écrivez tout ce que vous gardez « dans la tête ». Distinguez tâches et responsabilité d’y penser, puis négociez une répartition explicite et réaliste."]},{"h":"Quand chercher du soutien ?","p":["Si la surcharge entraîne une détresse durable, un soutien individuel ou familial peut être utile."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['stress-quand-le-corps-reste-en-alerte','burnout-comprendre-l-epuisement-professionnel','le-stress-au-travail-n-est-pas-toujours-individuel']::text[], 1, 'sage', 'a_relire', false, null, 24, false, false),
  ('burnout-comprendre-l-epuisement-professionnel', 'Burnout : comprendre l’épuisement professionnel', 'Stress et épuisement', 'Le burnout est un phénomène lié au contexte professionnel, associé à un stress chronique au travail qui n’a pas été géré avec succès. Il peut comporter épuisement, distance mentale ou cynisme envers le travail, et sentiment d’efficacité diminuée. Ce n’est pas un diagnostic médical en soi.', array['Le burnout est un phénomène lié au contexte professionnel, associé à un stress chronique au travail qui n’a pas été géré avec succès. Il peut comporter épuisement, distance mentale ou cynisme envers le travail, et sentiment d’efficacité diminuée. Ce n’est pas un diagnostic médical en soi.']::text[], '[{"h":"Une situation du quotidien","p":["Un salarié qui aimait son métier se sent vidé avant même de commencer, devient détaché et doute de toutes ses compétences."]},{"h":"Un premier pas possible","p":["Ne réduisez pas la réponse à « mieux gérer votre stress » : charge de travail, horaires, autonomie et soutien organisationnel comptent. Documentez les difficultés et recherchez des ajustements possibles."]},{"h":"Quand chercher du soutien ?","p":["Un professionnel peut évaluer une dépression, un trouble anxieux ou une autre affection qui pourrait coexister."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['stress-quand-le-corps-reste-en-alerte','surcharge-mentale-porter-l-invisible','le-stress-au-travail-n-est-pas-toujours-individuel']::text[], 1, 'forest', 'a_relire', false, null, 25, false, false),
  ('le-stress-au-travail-n-est-pas-toujours-individuel', 'Le stress au travail n’est pas toujours individuel', 'Stress et épuisement', 'Les conseils de respiration peuvent être utiles, mais ils ne remplacent pas des conditions de travail soutenables. Les objectifs irréalistes, l’insécurité de l’emploi ou le harcèlement exigent aussi des réponses organisationnelles.', array['Les conseils de respiration peuvent être utiles, mais ils ne remplacent pas des conditions de travail soutenables. Les objectifs irréalistes, l’insécurité de l’emploi ou le harcèlement exigent aussi des réponses organisationnelles.']::text[], '[{"h":"Une situation du quotidien","p":["Une salariée culpabilise de ne pas « être assez résistante » alors que les attentes changent chaque jour sans ressources supplémentaires."]},{"h":"Un premier pas possible","p":["Notez les demandes, clarifiez les priorités avec votre responsable lorsque c’est possible, recherchez des alliés et informez-vous sur vos droits et dispositifs de soutien."]},{"h":"Quand chercher du soutien ?","p":["En cas de harcèlement, de violence ou d’épuisement important, cherchez une aide adaptée et des conseils professionnels indépendants."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['stress-quand-le-corps-reste-en-alerte','surcharge-mentale-porter-l-invisible','burnout-comprendre-l-epuisement-professionnel']::text[], 1, 'gold', 'a_relire', false, null, 26, false, false),
  ('parents-epuises-quand-on-aime-et-qu-on-n-en-peut-plus', 'Parents épuisés : quand on aime et qu’on n’en peut plus', 'Stress et épuisement', 'Aimer ses enfants n’empêche pas d’être dépassé par le bruit, les nuits courtes ou les demandes constantes. L’épuisement parental n’est pas automatiquement un burnout professionnel ni une preuve de manque d’amour.', array['Aimer ses enfants n’empêche pas d’être dépassé par le bruit, les nuits courtes ou les demandes constantes. L’épuisement parental n’est pas automatiquement un burnout professionnel ni une preuve de manque d’amour.']::text[], '[{"h":"Une situation du quotidien","p":["Après une journée pleine, un parent peut rêver de silence et se sentir coupable aussitôt."]},{"h":"Un premier pas possible","p":["Identifiez un moment de récupération réaliste, même bref. Demandez une aide concrète, simplifiez une exigence non essentielle et partagez les responsabilités plutôt que de tout porter seul."]},{"h":"Quand chercher du soutien ?","p":["Si vous craignez de perdre le contrôle, mettez les enfants en sécurité et demandez immédiatement du relais ou une aide urgente."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['stress-quand-le-corps-reste-en-alerte','surcharge-mentale-porter-l-invisible','burnout-comprendre-l-epuisement-professionnel']::text[], 1, 'sage', 'a_relire', false, null, 27, false, false),
  ('le-deuil-n-a-pas-de-calendrier', 'Le deuil n’a pas de calendrier', 'Deuil et événements difficiles', 'Le deuil peut mêler tristesse, colère, soulagement, culpabilité, engourdissement ou moments de joie. Il n’existe pas une succession obligatoire d’étapes identiques pour tous.', array['Le deuil peut mêler tristesse, colère, soulagement, culpabilité, engourdissement ou moments de joie. Il n’existe pas une succession obligatoire d’étapes identiques pour tous.']::text[], '[{"h":"Une situation du quotidien","p":["Après un décès, quelqu’un peut gérer les démarches avec efficacité puis s’effondrer plusieurs semaines plus tard."]},{"h":"Un premier pas possible","p":["Autorisez des rythmes différents. Cherchez un soutien respectueux de vos traditions, de votre foi et de vos besoins personnels. Vous pouvez garder un lien symbolique avec la personne disparue."]},{"h":"Quand chercher du soutien ?","p":["Si la souffrance reste extrêmement intense, empêche durablement de vivre ou s’accompagne de danger, consultez un professionnel."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['quand-on-perd-un-parent-a-l-age-adulte','le-deuil-perinatal-merite-d-etre-reconnu','parler-de-la-mort-avec-un-enfant']::text[], 1, 'forest', 'a_relire', false, null, 28, true, false),
  ('quand-on-perd-un-parent-a-l-age-adulte', 'Quand on perd un parent à l’âge adulte', 'Deuil et événements difficiles', 'Perdre un parent peut bouleverser le sentiment de sécurité, les relations familiales et la manière de se percevoir, quel que soit son âge. Les responsabilités liées aux funérailles peuvent laisser peu de place à l’émotion.', array['Perdre un parent peut bouleverser le sentiment de sécurité, les relations familiales et la manière de se percevoir, quel que soit son âge. Les responsabilités liées aux funérailles peuvent laisser peu de place à l’émotion.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne organise les cérémonies, reçoit les proches, puis ressent un vide profond lorsque tout le monde repart."]},{"h":"Un premier pas possible","p":["Acceptez que vos émotions changent. Parlez de souvenirs si vous le souhaitez et autorisez-vous à poser des limites aux attentes de l’entourage."]},{"h":"Quand chercher du soutien ?","p":["Un accompagnement peut aider si le deuil devient particulièrement difficile ou réactive d’anciennes blessures."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['le-deuil-n-a-pas-de-calendrier','le-deuil-perinatal-merite-d-etre-reconnu','parler-de-la-mort-avec-un-enfant']::text[], 1, 'gold', 'a_relire', false, null, 29, true, false),
  ('le-deuil-perinatal-merite-d-etre-reconnu', 'Le deuil périnatal mérite d’être reconnu', 'Deuil et événements difficiles', 'Une fausse couche, une mort fœtale ou la perte d’un nouveau-né peuvent provoquer un chagrin profond. La durée de la grossesse ne détermine pas la légitimité de la peine.', array['Une fausse couche, une mort fœtale ou la perte d’un nouveau-né peuvent provoquer un chagrin profond. La durée de la grossesse ne détermine pas la légitimité de la peine.']::text[], '[{"h":"Une situation du quotidien","p":["« Vous êtes jeunes, vous en aurez un autre » peut blesser une famille qui vient de perdre cet enfant précis."]},{"h":"Un premier pas possible","p":["Utilisez le langage choisi par les parents, proposez une présence concrète et respectez les rituels qu’ils souhaitent. Évitez de comparer leur perte à une autre."]},{"h":"Quand chercher du soutien ?","p":["Un soutien médical et psychologique adapté est important, notamment en cas de détresse intense, de symptômes traumatiques ou de complications physiques."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['le-deuil-n-a-pas-de-calendrier','quand-on-perd-un-parent-a-l-age-adulte','parler-de-la-mort-avec-un-enfant']::text[], 1, 'sage', 'a_relire', false, null, 30, true, true),
  ('parler-de-la-mort-avec-un-enfant', 'Parler de la mort avec un enfant', 'Deuil et événements difficiles', 'Les enfants comprennent la mort différemment selon leur développement. Ils peuvent poser des questions répétitives, jouer comme d’habitude ou craindre de perdre d’autres proches.', array['Les enfants comprennent la mort différemment selon leur développement. Ils peuvent poser des questions répétitives, jouer comme d’habitude ou craindre de perdre d’autres proches.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant demande chaque soir si sa grand-mère reviendra, même après avoir assisté aux funérailles."]},{"h":"Un premier pas possible","p":["Utilisez des mots simples et vrais : « Elle est morte, son corps ne fonctionne plus ». Évitez les formulations qui risquent de rendre le sommeil effrayant. Rassurez sur les personnes qui prennent soin de lui."]},{"h":"Quand chercher du soutien ?","p":["Consultez si la détresse est persistante, intense ou compromet fortement son quotidien."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['le-deuil-n-a-pas-de-calendrier','quand-on-perd-un-parent-a-l-age-adulte','le-deuil-perinatal-merite-d-etre-reconnu']::text[], 1, 'forest', 'a_relire', false, null, 31, true, true),
  ('apres-un-evenement-traumatisant', 'Après un événement traumatisant', 'Deuil et événements difficiles', 'Après un accident, une agression ou une autre expérience terrifiante, des réactions de peur, d’hypervigilance, de cauchemars ou d’évitement peuvent apparaître. Elles ne signifient pas toutes qu’un trouble de stress post-traumatique s’installera.', array['Après un accident, une agression ou une autre expérience terrifiante, des réactions de peur, d’hypervigilance, de cauchemars ou d’évitement peuvent apparaître. Elles ne signifient pas toutes qu’un trouble de stress post-traumatique s’installera.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne sursaute au bruit des moteurs après un accident de circulation."]},{"h":"Un premier pas possible","p":["Privilégiez la sécurité, le soutien et le retour progressif à des routines choisies. Il n’est pas nécessaire de raconter les détails de l’événement à tout le monde."]},{"h":"Quand chercher du soutien ?","p":["Si les symptômes persistent, s’aggravent ou sont très invalidants, une évaluation spécialisée du traumatisme est indiquée ; évitez les exercices d’exposition improvisés."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['le-deuil-n-a-pas-de-calendrier','quand-on-perd-un-parent-a-l-age-adulte','le-deuil-perinatal-merite-d-etre-reconnu']::text[], 1, 'gold', 'a_relire', false, null, 32, true, true),
  ('baby-blues-ou-depression-postnatale', 'Baby blues ou dépression postnatale ?', 'Santé mentale périnatale', 'Après un accouchement, des changements émotionnels peuvent survenir. Le baby blues est généralement transitoire, tandis qu’une dépression postnatale peut être plus durable et affecter l’humeur, l’énergie, l’attachement ou le quotidien. Les symptômes méritent d’être évalués, sans culpabilisation.', array['Après un accouchement, des changements émotionnels peuvent survenir. Le baby blues est généralement transitoire, tandis qu’une dépression postnatale peut être plus durable et affecter l’humeur, l’énergie, l’attachement ou le quotidien. Les symptômes méritent d’être évalués, sans culpabilisation.']::text[], '[{"h":"Une situation du quotidien","p":["Une mère entend « Tu devrais être heureuse » alors qu’elle pleure souvent et ne reconnaît plus son état habituel."]},{"h":"Un premier pas possible","p":["Parlez honnêtement à une sage-femme, un médecin ou un professionnel de santé. Demandez de l’aide pour dormir, manger et récupérer : le soutien pratique compte."]},{"h":"Quand chercher du soutien ?","p":["Toute idée de se faire du mal ou de faire du mal au bébé, confusion importante ou perte de contact avec la réalité impose une évaluation urgente."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['depression-pendant-la-grossesse-en-parler','anxiete-perinatale-quand-les-inquietudes-envahissent-tout','toc-perinatal-comprendre-les-pensees-qui-font-peur']::text[], 1, 'sage', 'a_relire', false, null, 33, true, true),
  ('depression-pendant-la-grossesse-en-parler', 'Dépression pendant la grossesse : en parler', 'Santé mentale périnatale', 'La grossesse ne protège pas de la dépression. Tristesse, perte d’intérêt, anxiété ou épuisement peuvent être minimisés parce que l’entourage se concentre sur le bébé.', array['La grossesse ne protège pas de la dépression. Tristesse, perte d’intérêt, anxiété ou épuisement peuvent être minimisés parce que l’entourage se concentre sur le bébé.']::text[], '[{"h":"Une situation du quotidien","p":["Une femme enceinte n’ose pas dire qu’elle ne ressent pas la joie attendue."]},{"h":"Un premier pas possible","p":["Expliquez vos symptômes au professionnel qui suit votre grossesse. Les décisions de traitement doivent tenir compte de votre santé, de la grossesse et de vos préférences."]},{"h":"Quand chercher du soutien ?","p":["Ne commencez ni n’arrêtez un traitement sans conseil médical ; une détresse importante nécessite une prise en charge adaptée."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['baby-blues-ou-depression-postnatale','anxiete-perinatale-quand-les-inquietudes-envahissent-tout','toc-perinatal-comprendre-les-pensees-qui-font-peur']::text[], 1, 'forest', 'a_relire', false, null, 34, true, true),
  ('anxiete-perinatale-quand-les-inquietudes-envahissent-tout', 'Anxiété périnatale : quand les inquiétudes envahissent tout', 'Santé mentale périnatale', 'Pendant la grossesse et après la naissance, certaines inquiétudes sont fréquentes. Elles deviennent préoccupantes lorsqu’elles sont persistantes, envahissantes ou poussent à des vérifications répétées et épuisantes.', array['Pendant la grossesse et après la naissance, certaines inquiétudes sont fréquentes. Elles deviennent préoccupantes lorsqu’elles sont persistantes, envahissantes ou poussent à des vérifications répétées et épuisantes.']::text[], '[{"h":"Une situation du quotidien","p":["Une mère vérifie sans cesse si son bébé respire, au point de ne presque plus dormir."]},{"h":"Un premier pas possible","p":["Parlez de vos craintes sans honte. Distinguez les consignes de sécurité recommandées par les soignants des vérifications répétitives dictées par l’angoisse."]},{"h":"Quand chercher du soutien ?","p":["Un professionnel périnatal peut évaluer l’anxiété et proposer une aide appropriée ; ne réduisez jamais les recommandations médicales de sécurité."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['baby-blues-ou-depression-postnatale','depression-pendant-la-grossesse-en-parler','toc-perinatal-comprendre-les-pensees-qui-font-peur']::text[], 1, 'gold', 'a_relire', false, null, 35, true, true),
  ('toc-perinatal-comprendre-les-pensees-qui-font-peur', 'TOC périnatal : comprendre les pensées qui font peur', 'Santé mentale périnatale', 'Le TOC périnatal peut comprendre des pensées intrusives non désirées concernant le bébé et des rituels de vérification ou d’évitement. Ces pensées peuvent provoquer une honte intense. Elles ne sont pas équivalentes à une intention de nuire.', array['Le TOC périnatal peut comprendre des pensées intrusives non désirées concernant le bébé et des rituels de vérification ou d’évitement. Ces pensées peuvent provoquer une honte intense. Elles ne sont pas équivalentes à une intention de nuire.']::text[], '[{"h":"Une situation du quotidien","p":["Une mère évite de changer son bébé parce qu’une image intrusive lui a fait peur."]},{"h":"Un premier pas possible","p":["Une évaluation spécialisée permet de distinguer TOC, anxiété, dépression et autres situations. L’écoute doit être sans jugement, tout en prenant la sécurité au sérieux."]},{"h":"Quand chercher du soutien ?","p":["Des idées de passage à l’acte, une confusion, des convictions délirantes ou des hallucinations demandent une évaluation urgente."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['baby-blues-ou-depression-postnatale','depression-pendant-la-grossesse-en-parler','anxiete-perinatale-quand-les-inquietudes-envahissent-tout']::text[], 1, 'sage', 'a_relire', false, null, 36, true, true),
  ('psychose-du-post-partum-reconnaitre-l-urgence', 'Psychose du post-partum : reconnaître l’urgence', 'Santé mentale périnatale', 'La psychose du post-partum est une urgence psychiatrique rare mais grave. Elle peut s’accompagner de confusion, de changements rapides d’humeur, de convictions inhabituelles, d’hallucinations ou de comportements très désorganisés.', array['La psychose du post-partum est une urgence psychiatrique rare mais grave. Elle peut s’accompagner de confusion, de changements rapides d’humeur, de convictions inhabituelles, d’hallucinations ou de comportements très désorganisés.']::text[], '[{"h":"Une situation du quotidien","p":["Une famille remarque qu’une mère récemment accouchée ne dort presque plus, semble désorientée et exprime des croyances qui ne correspondent pas à la réalité."]},{"h":"Un premier pas possible","p":["Ne laissez pas la personne seule avec la responsabilité du bébé ; assurez une présence sécurisante et recherchez une évaluation médicale urgente."]},{"h":"Quand chercher du soutien ?","p":["Il ne faut pas attendre qu’un article ou un programme en ligne suffise : une prise en charge immédiate est nécessaire."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['baby-blues-ou-depression-postnatale','depression-pendant-la-grossesse-en-parler','anxiete-perinatale-quand-les-inquietudes-envahissent-tout']::text[], 1, 'forest', 'a_relire', false, null, 37, true, true),
  ('les-peres-aussi-peuvent-aller-mal-apres-une-naissance', 'Les pères aussi peuvent aller mal après une naissance', 'Santé mentale périnatale', 'L’arrivée d’un enfant peut modifier le sommeil, les responsabilités, les finances et la relation de couple. Certains pères ou partenaires traversent une dépression ou une anxiété qui reste peu reconnue.', array['L’arrivée d’un enfant peut modifier le sommeil, les responsabilités, les finances et la relation de couple. Certains pères ou partenaires traversent une dépression ou une anxiété qui reste peu reconnue.']::text[], '[{"h":"Une situation du quotidien","p":["Un père devient irritable, se retire et se reproche de ne pas être à la hauteur."]},{"h":"Un premier pas possible","p":["Ouvrez un espace de parole sans compétition de souffrance. Encouragez une répartition réaliste des tâches et l’accès aux soins si les symptômes persistent."]},{"h":"Quand chercher du soutien ?","p":["Les pensées suicidaires ou une détérioration importante nécessitent une aide professionnelle rapide."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['baby-blues-ou-depression-postnatale','depression-pendant-la-grossesse-en-parler','anxiete-perinatale-quand-les-inquietudes-envahissent-tout']::text[], 1, 'gold', 'a_relire', false, null, 38, true, true),
  ('neurodiversite-de-quoi-parle-t-on', 'Neurodiversité : de quoi parle-t-on ?', 'Neurodiversité et neurodéveloppement', 'La neurodiversité décrit la diversité des fonctionnements neurologiques humains. Le terme neurodivergent peut concerner notamment l’autisme, le TDAH et certaines différences d’apprentissage. Ce n’est pas un diagnostic unique.', array['La neurodiversité décrit la diversité des fonctionnements neurologiques humains. Le terme neurodivergent peut concerner notamment l’autisme, le TDAH et certaines différences d’apprentissage. Ce n’est pas un diagnostic unique.']::text[], '[{"h":"Une situation du quotidien","p":["Dans une classe, deux enfants peuvent apprendre différemment sans que l’un soit moins intelligent que l’autre."]},{"h":"Un premier pas possible","p":["Remplacez « Pourquoi n’est-il pas comme les autres ? » par « Qu’est-ce qui l’aide à apprendre et à participer ? ». Écoutez les personnes concernées et adaptez l’environnement."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation professionnelle peut être utile lorsque des difficultés importantes exigent des aménagements ou un accompagnement spécifique."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['autisme-comprendre-sans-reduire-une-personne-a-un-cliche','tdah-plus-qu-un-enfant-qui-bouge','dyslexie-et-troubles-des-apprentissages']::text[], 1, 'sage', 'a_relire', false, null, 39, false, false),
  ('autisme-comprendre-sans-reduire-une-personne-a-un-cliche', 'Autisme : comprendre sans réduire une personne à un cliché', 'Neurodiversité et neurodéveloppement', 'L’autisme correspond à un ensemble varié de particularités du développement touchant notamment la communication sociale, les intérêts, les routines et parfois le traitement sensoriel. Les profils et besoins diffèrent beaucoup d’une personne à l’autre.', array['L’autisme correspond à un ensemble varié de particularités du développement touchant notamment la communication sociale, les intérêts, les routines et parfois le traitement sensoriel. Les profils et besoins diffèrent beaucoup d’une personne à l’autre.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant peut parler très bien mais être épuisé par les changements imprévus ou le bruit d’une salle de classe."]},{"h":"Un premier pas possible","p":["Proposez des consignes claires, des transitions annoncées et des adaptations sensorielles lorsque nécessaires. Évitez de supposer que toute personne autiste se ressemble."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation adaptée et des soutiens individualisés peuvent aider sans chercher à effacer l’identité de la personne."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','tdah-plus-qu-un-enfant-qui-bouge','dyslexie-et-troubles-des-apprentissages']::text[], 1, 'forest', 'a_relire', false, null, 40, false, false),
  ('tdah-plus-qu-un-enfant-qui-bouge', 'TDAH : plus qu’un enfant qui bouge', 'Neurodiversité et neurodéveloppement', 'Le trouble du déficit de l’attention avec ou sans hyperactivité peut concerner l’attention, l’impulsivité, l’organisation, la régulation émotionnelle et l’activité motrice. Il existe aussi chez les adultes.', array['Le trouble du déficit de l’attention avec ou sans hyperactivité peut concerner l’attention, l’impulsivité, l’organisation, la régulation émotionnelle et l’activité motrice. Il existe aussi chez les adultes.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne oublie des échéances malgré des efforts sincères, puis se reproche son « manque de discipline »."]},{"h":"Un premier pas possible","p":["Essayez des rappels visibles, des tâches découpées et un environnement moins distrayant. Ces stratégies peuvent aider, mais ne prouvent ni n’excluent un diagnostic."]},{"h":"Quand chercher du soutien ?","p":["Un professionnel qualifié peut évaluer le TDAH et rechercher d’autres explications possibles aux difficultés."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','autisme-comprendre-sans-reduire-une-personne-a-un-cliche','dyslexie-et-troubles-des-apprentissages']::text[], 1, 'gold', 'a_relire', false, null, 41, true, true),
  ('dyslexie-et-troubles-des-apprentissages', 'Dyslexie et troubles des apprentissages', 'Neurodiversité et neurodéveloppement', 'La dyslexie affecte notamment l’apprentissage de la lecture et de l’orthographe. D’autres troubles spécifiques peuvent toucher les mathématiques ou l’écriture. Ils ne signifient pas un manque d’intelligence ou d’effort.', array['La dyslexie affecte notamment l’apprentissage de la lecture et de l’orthographe. D’autres troubles spécifiques peuvent toucher les mathématiques ou l’écriture. Ils ne signifient pas un manque d’intelligence ou d’effort.']::text[], '[{"h":"Une situation du quotidien","p":["Un élève comprend très bien une histoire racontée, mais lit lentement et s’épuise devant un texte."]},{"h":"Un premier pas possible","p":["Privilégiez des supports accessibles, davantage de temps si nécessaire, et des méthodes d’apprentissage adaptées. Valorisez aussi les compétences de l’enfant."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation spécialisée peut préciser les besoins et guider les aménagements scolaires."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','autisme-comprendre-sans-reduire-une-personne-a-un-cliche','tdah-plus-qu-un-enfant-qui-bouge']::text[], 1, 'sage', 'a_relire', false, null, 42, false, false),
  ('sensibilites-sensorielles-quand-le-monde-est-trop-intense', 'Sensibilités sensorielles : quand le monde est trop intense', 'Neurodiversité et neurodéveloppement', 'Le bruit, la lumière, les textures ou les odeurs peuvent être vécus très différemment. Certaines personnes sont particulièrement sensibles, d’autres recherchent davantage de sensations. Cela peut accompagner divers profils neurodéveloppementaux.', array['Le bruit, la lumière, les textures ou les odeurs peuvent être vécus très différemment. Certaines personnes sont particulièrement sensibles, d’autres recherchent davantage de sensations. Cela peut accompagner divers profils neurodéveloppementaux.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant se bouche les oreilles lors d’une fête familiale bruyante ; l’entourage croit qu’il est impoli."]},{"h":"Un premier pas possible","p":["Demandez ce qui gêne, proposez un endroit plus calme et autorisez des pauses. Évitez de forcer une exposition à des sensations insupportables."]},{"h":"Quand chercher du soutien ?","p":["Si les sensibilités perturbent fortement le quotidien, un professionnel compétent peut aider à identifier des adaptations."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','autisme-comprendre-sans-reduire-une-personne-a-un-cliche','tdah-plus-qu-un-enfant-qui-bouge']::text[], 1, 'forest', 'a_relire', false, null, 43, false, false),
  ('autisme-et-tdah-chez-les-filles-et-les-femmes', 'Autisme et TDAH chez les filles et les femmes', 'Neurodiversité et neurodéveloppement', 'Certaines filles et femmes apprennent à masquer leurs difficultés ou présentent des signes moins attendus, ce qui peut contribuer à un repérage tardif. Aucun portrait unique ne permet de reconnaître ces profils.', array['Certaines filles et femmes apprennent à masquer leurs difficultés ou présentent des signes moins attendus, ce qui peut contribuer à un repérage tardif. Aucun portrait unique ne permet de reconnaître ces profils.']::text[], '[{"h":"Une situation du quotidien","p":["Une adolescente paraît discrète à l’école mais rentre épuisée après avoir passé la journée à s’adapter."]},{"h":"Un premier pas possible","p":["Écoutez les difficultés vécues au-delà des résultats scolaires ou de l’apparence extérieure. Demandez quels efforts invisibles sont nécessaires pour « tenir »."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation spécialisée peut être pertinente si les difficultés sont persistantes et affectent le fonctionnement."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','autisme-comprendre-sans-reduire-une-personne-a-un-cliche','tdah-plus-qu-un-enfant-qui-bouge']::text[], 1, 'gold', 'a_relire', false, null, 44, false, false),
  ('adapter-l-ecole-et-le-travail-aux-besoins-differents', 'Adapter l’école et le travail aux besoins différents', 'Neurodiversité et neurodéveloppement', 'L’accessibilité ne consiste pas à abaisser les attentes, mais à réduire des obstacles inutiles. Consignes écrites, horaires prévisibles, pauses, outils numériques ou espaces calmes peuvent faire une différence.', array['L’accessibilité ne consiste pas à abaisser les attentes, mais à réduire des obstacles inutiles. Consignes écrites, horaires prévisibles, pauses, outils numériques ou espaces calmes peuvent faire une différence.']::text[], '[{"h":"Une situation du quotidien","p":["Un salarié comprend mieux les tâches lorsqu’elles sont formulées par écrit plutôt que données à la volée."]},{"h":"Un premier pas possible","p":["Commencez par demander à la personne ce qui l’aide réellement ; une adaptation utile pour l’une peut gêner une autre."]},{"h":"Quand chercher du soutien ?","p":["Pour des aménagements formels, renseignez-vous sur les procédures locales et les professionnels compétents."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['neurodiversite-de-quoi-parle-t-on','autisme-comprendre-sans-reduire-une-personne-a-un-cliche','tdah-plus-qu-un-enfant-qui-bouge']::text[], 1, 'sage', 'a_relire', false, null, 45, false, false),
  ('tics-comprendre-ces-mouvements-et-sons-involontaires', 'Tics : comprendre ces mouvements et sons involontaires', 'Tics et Tourette', 'Les tics sont des mouvements ou vocalisations soudains et répétés, souvent difficiles à contrôler. Ils peuvent varier selon la fatigue, le stress et les situations. Un tic n’est pas nécessairement un comportement volontaire ou une provocation.', array['Les tics sont des mouvements ou vocalisations soudains et répétés, souvent difficiles à contrôler. Ils peuvent varier selon la fatigue, le stress et les situations. Un tic n’est pas nécessairement un comportement volontaire ou une provocation.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant cligne fréquemment des yeux ; des adultes lui répètent « Arrête ça » sans comprendre ce qu’il vit."]},{"h":"Un premier pas possible","p":["Évitez les remarques répétées et la moquerie. Observez si le tic gêne, fait mal ou attire des réactions blessantes."]},{"h":"Quand chercher du soutien ?","p":["Un médecin peut vérifier les causes possibles et orienter vers une évaluation si les tics persistent ou deviennent gênants."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['syndrome-de-gilles-de-la-tourette-depasser-les-caricatures']::text[], 1, 'forest', 'a_relire', false, null, 46, false, false),
  ('syndrome-de-gilles-de-la-tourette-depasser-les-caricatures', 'Syndrome de Gilles de la Tourette : dépasser les caricatures', 'Tics et Tourette', 'Le syndrome de Gilles de la Tourette comporte des tics moteurs et vocaux qui évoluent dans le temps. Les jurons involontaires, souvent montrés dans les médias, ne concernent pas toutes les personnes.', array['Le syndrome de Gilles de la Tourette comporte des tics moteurs et vocaux qui évoluent dans le temps. Les jurons involontaires, souvent montrés dans les médias, ne concernent pas toutes les personnes.']::text[], '[{"h":"Une situation du quotidien","p":["Un adolescent évite les présentations orales parce qu’il redoute les réactions à ses tics."]},{"h":"Un premier pas possible","p":["Demandez quelles adaptations seraient utiles : temps supplémentaire, pauses, sensibilisation respectueuse des camarades. Ne demandez pas à la personne de se justifier constamment."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation spécialisée permet de discuter des traitements possibles lorsque les tics provoquent douleur, détresse ou handicap."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['tics-comprendre-ces-mouvements-et-sons-involontaires']::text[], 1, 'gold', 'a_relire', false, null, 47, false, false),
  ('refus-scolaire-regarder-derriere-le-comportement', 'Refus scolaire : regarder derrière le comportement', 'Enfants, adolescents et familles', 'Lorsqu’un enfant ne parvient plus à aller à l’école, il peut vivre de l’anxiété, des difficultés d’apprentissage, du harcèlement, des problèmes de santé ou plusieurs facteurs à la fois. Parler de « paresse » ferme souvent le dialogue.', array['Lorsqu’un enfant ne parvient plus à aller à l’école, il peut vivre de l’anxiété, des difficultés d’apprentissage, du harcèlement, des problèmes de santé ou plusieurs facteurs à la fois. Parler de « paresse » ferme souvent le dialogue.']::text[], '[{"h":"Une situation du quotidien","p":["Un enfant pleure chaque matin mais joue normalement le week-end : cela ne prouve pas qu’il simule."]},{"h":"Un premier pas possible","p":["Cherchez avec lui ce qui rend l’école difficile. Collaborez avec l’établissement, prévoyez des adaptations progressives et vérifiez les enjeux de sécurité."]},{"h":"Quand chercher du soutien ?","p":["Une évaluation pédiatrique ou psychologique est recommandée lorsque l’absence se prolonge ou que la détresse est importante."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['aider-un-enfant-a-nommer-ses-emotions','harcelement-scolaire-ecouter-et-agir']::text[], 1, 'sage', 'a_relire', false, null, 48, true, true),
  ('aider-un-enfant-a-nommer-ses-emotions', 'Aider un enfant à nommer ses émotions', 'Enfants, adolescents et familles', 'Les enfants apprennent progressivement à reconnaître et exprimer leurs émotions. Ils ont besoin de mots, de modèles et d’un adulte qui les aide à réguler plutôt que de simplement exiger le calme.', array['Les enfants apprennent progressivement à reconnaître et exprimer leurs émotions. Ils ont besoin de mots, de modèles et d’un adulte qui les aide à réguler plutôt que de simplement exiger le calme.']::text[], '[{"h":"Une situation du quotidien","p":["Après une dispute, un enfant crie « Je te déteste » alors qu’il se sent surtout frustré et dépassé."]},{"h":"Un premier pas possible","p":["Essayez : « Tu es très en colère parce que le jeu s’est arrêté ». Posez ensuite une limite claire sur les gestes dangereux, sans condamner l’émotion."]},{"h":"Quand chercher du soutien ?","p":["Des crises fréquentes, intenses ou associées à des difficultés de développement méritent une évaluation adaptée."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['refus-scolaire-regarder-derriere-le-comportement','harcelement-scolaire-ecouter-et-agir']::text[], 1, 'forest', 'a_relire', false, null, 49, true, true),
  ('harcelement-scolaire-ecouter-et-agir', 'Harcèlement scolaire : écouter et agir', 'Enfants, adolescents et familles', 'Le harcèlement implique des comportements répétés qui blessent ou excluent, avec un déséquilibre de pouvoir. Il peut être verbal, physique, relationnel ou numérique.', array['Le harcèlement implique des comportements répétés qui blessent ou excluent, avec un déséquilibre de pouvoir. Il peut être verbal, physique, relationnel ou numérique.']::text[], '[{"h":"Une situation du quotidien","p":["Un élève ne veut plus prendre le bus scolaire parce qu’un groupe l’humilie chaque matin."]},{"h":"Un premier pas possible","p":["Croyez la parole de l’enfant, documentez les faits, contactez l’établissement et établissez un plan de protection. Ne lui demandez pas simplement d’ignorer les agressions."]},{"h":"Quand chercher du soutien ?","p":["Si sa sécurité ou sa santé mentale est menacée, sollicitez rapidement les autorités et professionnels compétents."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['refus-scolaire-regarder-derriere-le-comportement','aider-un-enfant-a-nommer-ses-emotions']::text[], 1, 'gold', 'a_relire', false, null, 50, true, true),
  ('5-4-3-2-1-revenir-a-l-instant-present', '5-4-3-2-1 : revenir à l’instant présent', 'Bien-être au quotidien', 'Lorsque les inquiétudes s’emballent, un exercice d’ancrage peut aider à porter attention à l’environnement. Il ne supprime pas la cause du stress, mais offre une pause pour choisir la suite.', array['Lorsque les inquiétudes s’emballent, un exercice d’ancrage peut aider à porter attention à l’environnement. Il ne supprime pas la cause du stress, mais offre une pause pour choisir la suite.']::text[], '[{"h":"Une situation du quotidien","p":["Dans une salle d’attente, une personne imagine dix scénarios inquiétants et remarque à peine ce qui l’entoure."]},{"h":"Un premier pas possible","p":["Regardez autour de vous : nommez cinq choses vues, quatre sensations de contact, trois sons, deux odeurs et une saveur ou sensation agréable. Adaptez les étapes si un sens n’est pas accessible."]},{"h":"Quand chercher du soutien ?","p":["Si l’exercice augmente le malaise ou les souvenirs traumatiques, arrêtez et choisissez une autre manière de vous stabiliser."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['respiration-carree-un-outil-pas-une-obligation','relaxation-musculaire-progressive-relacher-la-tension','sommeil-sortir-de-la-bataille-contre-la-nuit']::text[], 1, 'sage', 'a_relire', false, null, 51, true, true),
  ('respiration-carree-un-outil-pas-une-obligation', 'Respiration carrée : un outil, pas une obligation', 'Bien-être au quotidien', 'La respiration carrée consiste souvent à inspirer, faire une pause, expirer et faire une pause selon quatre temps. Elle ne convient pas à tout le monde, notamment si retenir son souffle est inconfortable.', array['La respiration carrée consiste souvent à inspirer, faire une pause, expirer et faire une pause selon quatre temps. Elle ne convient pas à tout le monde, notamment si retenir son souffle est inconfortable.']::text[], '[{"h":"Une situation du quotidien","p":["Avant une conversation difficile, une personne souhaite ralentir quelques instants."]},{"h":"Un premier pas possible","p":["Essayez une respiration douce et confortable, éventuellement avec des temps égaux, sans forcer. Si les pauses vous gênent, inspirez normalement et expirez lentement, sans compter strictement."]},{"h":"Quand chercher du soutien ?","p":["Arrêtez si vous avez des vertiges ou une gêne ; des symptômes respiratoires ou cardiaques nécessitent une évaluation médicale."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['5-4-3-2-1-revenir-a-l-instant-present','relaxation-musculaire-progressive-relacher-la-tension','sommeil-sortir-de-la-bataille-contre-la-nuit']::text[], 1, 'forest', 'a_relire', false, null, 52, false, false),
  ('relaxation-musculaire-progressive-relacher-la-tension', 'Relaxation musculaire progressive : relâcher la tension', 'Bien-être au quotidien', 'La relaxation musculaire progressive aide à remarquer la différence entre contraction et relâchement. Elle peut être utile lorsque le corps reste tendu, mais elle n’est pas indispensable à tous.', array['La relaxation musculaire progressive aide à remarquer la différence entre contraction et relâchement. Elle peut être utile lorsque le corps reste tendu, mais elle n’est pas indispensable à tous.']::text[], '[{"h":"Une situation du quotidien","p":["Après une journée de travail, quelqu’un remarque qu’il serre la mâchoire et relève les épaules."]},{"h":"Un premier pas possible","p":["Installez-vous confortablement. Contractez doucement un groupe musculaire quelques secondes, puis relâchez et observez. Évitez toute zone douloureuse, blessée ou déconseillée médicalement."]},{"h":"Quand chercher du soutien ?","p":["Si cet exercice provoque douleur ou malaise, interrompez-le ; un professionnel peut proposer une alternative."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['5-4-3-2-1-revenir-a-l-instant-present','respiration-carree-un-outil-pas-une-obligation','sommeil-sortir-de-la-bataille-contre-la-nuit']::text[], 1, 'gold', 'a_relire', false, null, 53, false, false),
  ('sommeil-sortir-de-la-bataille-contre-la-nuit', 'Sommeil : sortir de la bataille contre la nuit', 'Bien-être au quotidien', 'Des difficultés de sommeil peuvent être liées au stress, aux horaires, à la santé, à l’environnement ou à d’autres facteurs. Plus on cherche à « forcer » le sommeil, plus l’inquiétude peut augmenter.', array['Des difficultés de sommeil peuvent être liées au stress, aux horaires, à la santé, à l’environnement ou à d’autres facteurs. Plus on cherche à « forcer » le sommeil, plus l’inquiétude peut augmenter.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne regarde l’heure toute la nuit et calcule le nombre d’heures qu’il lui reste."]},{"h":"Un premier pas possible","p":["Essayez des horaires de lever réguliers, une transition apaisante avant le coucher et un environnement adapté lorsque possible. Évitez de traiter toute insomnie par de simples conseils d’hygiène."]},{"h":"Quand chercher du soutien ?","p":["Des troubles persistants, des ronflements avec pauses respiratoires ou une somnolence dangereuse méritent une consultation médicale."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['5-4-3-2-1-revenir-a-l-instant-present','respiration-carree-un-outil-pas-une-obligation','relaxation-musculaire-progressive-relacher-la-tension']::text[], 1, 'sage', 'a_relire', false, null, 54, false, false),
  ('resoudre-un-probleme-sans-se-noyer-dans-les-scenarios', 'Résoudre un problème sans se noyer dans les scénarios', 'Bien-être au quotidien', 'Un problème réel appelle parfois une action ; une inquiétude hypothétique n’a pas toujours de solution immédiate. Les distinguer permet d’utiliser son énergie autrement.', array['Un problème réel appelle parfois une action ; une inquiétude hypothétique n’a pas toujours de solution immédiate. Les distinguer permet d’utiliser son énergie autrement.']::text[], '[{"h":"Une situation du quotidien","p":["Une facture est due vendredi : c’est un problème concret. « Et si je perdais tout l’an prochain ? » est une hypothèse qui peut tourner en boucle."]},{"h":"Un premier pas possible","p":["Définissez le problème précisément, listez plusieurs options, comparez-les, choisissez une première étape et faites le point ensuite. Vous n’avez pas besoin d’une solution parfaite."]},{"h":"Quand chercher du soutien ?","p":["Si le problème implique violence, urgence financière ou danger, cherchez aussi une aide spécialisée et des ressources concrètes."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['5-4-3-2-1-revenir-a-l-instant-present','respiration-carree-un-outil-pas-une-obligation','relaxation-musculaire-progressive-relacher-la-tension']::text[], 1, 'forest', 'a_relire', false, null, 55, false, false),
  ('chez-nous-on-est-forts-quand-la-force-devient-un-silence', '« Chez nous, on est forts » : quand la force devient un silence', 'Culture, foi et société', 'Le courage transmis dans certaines familles peut être une ressource précieuse. Mais lorsqu’il devient l’obligation de ne jamais montrer sa souffrance, il peut isoler. Les cultures africaines sont diverses : aucune famille ne représente toutes les autres.', array['Le courage transmis dans certaines familles peut être une ressource précieuse. Mais lorsqu’il devient l’obligation de ne jamais montrer sa souffrance, il peut isoler. Les cultures africaines sont diverses : aucune famille ne représente toutes les autres.']::text[], '[{"h":"Une situation du quotidien","p":["Une femme assume travail, enfants et proches, puis répond toujours « Ça va, Dieu merci » même lorsqu’elle pleure seule."]},{"h":"Un premier pas possible","p":["Essayons de redéfinir la force : reconnaître ses émotions, poser des limites et demander du soutien peut aussi demander du courage. Écouter sans minimiser ouvre un espace de confiance."]},{"h":"Quand chercher du soutien ?","p":["Une détresse durable mérite d’être prise au sérieux, même chez quelqu’un qui continue à remplir toutes ses responsabilités."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['foi-priere-et-soutien-psychologique-faut-il-choisir','ne-raconte-pas-nos-problemes-le-poids-du-secret-familial','la-honte-n-est-pas-un-diagnostic']::text[], 1, 'gold', 'a_relire', true, 1, 56, false, false),
  ('foi-priere-et-soutien-psychologique-faut-il-choisir', 'Foi, prière et soutien psychologique : faut-il choisir ?', 'Culture, foi et société', 'Pour de nombreuses personnes, la foi apporte du sens, de l’espérance et un soutien communautaire. Elle ne rend pas automatiquement immunisé contre la dépression, l’anxiété ou les troubles psychiques. Un accompagnement religieux et des soins adaptés peuvent parfois coexister.', array['Pour de nombreuses personnes, la foi apporte du sens, de l’espérance et un soutien communautaire. Elle ne rend pas automatiquement immunisé contre la dépression, l’anxiété ou les troubles psychiques. Un accompagnement religieux et des soins adaptés peuvent parfois coexister.']::text[], '[{"h":"Une situation du quotidien","p":["Un croyant hésite à consulter parce qu’il craint qu’on lui reproche un manque de foi."]},{"h":"Un premier pas possible","p":["Vous pouvez demander un soutien spirituel respectueux tout en consultant un professionnel qualifié. Personne ne devrait vous imposer la honte, des pratiques dangereuses ou l’arrêt d’un traitement prescrit."]},{"h":"Quand chercher du soutien ?","p":["Des symptômes graves, une confusion ou un danger immédiat nécessitent des soins urgents, indépendamment des convictions."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['chez-nous-on-est-forts-quand-la-force-devient-un-silence','ne-raconte-pas-nos-problemes-le-poids-du-secret-familial','la-honte-n-est-pas-un-diagnostic']::text[], 1, 'sage', 'a_relire', false, null, 57, false, false),
  ('ne-raconte-pas-nos-problemes-le-poids-du-secret-familial', '« Ne raconte pas nos problèmes » : le poids du secret familial', 'Culture, foi et société', 'La discrétion peut protéger l’intimité. Mais elle devient pesante lorsqu’elle empêche de parler de violence, de souffrance ou de difficultés qui nécessitent de l’aide.', array['La discrétion peut protéger l’intimité. Mais elle devient pesante lorsqu’elle empêche de parler de violence, de souffrance ou de difficultés qui nécessitent de l’aide.']::text[], '[{"h":"Une situation du quotidien","p":["Un adolescent n’ose pas raconter ce qui se passe à la maison parce qu’on lui a appris que « les histoires de famille restent en famille »."]},{"h":"Un premier pas possible","p":["Distinguez confidentialité et isolement. Choisissez une personne fiable, respectueuse des limites, et demandez un soutien adapté. La sécurité passe avant la réputation familiale."]},{"h":"Quand chercher du soutien ?","p":["En cas de violence ou de danger pour un enfant, contactez les services de protection et d’urgence compétents."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['chez-nous-on-est-forts-quand-la-force-devient-un-silence','foi-priere-et-soutien-psychologique-faut-il-choisir','la-honte-n-est-pas-un-diagnostic']::text[], 1, 'forest', 'a_relire', false, null, 58, false, false),
  ('la-honte-n-est-pas-un-diagnostic', 'La honte n’est pas un diagnostic', 'Culture, foi et société', 'La stigmatisation peut faire croire qu’une difficulté psychologique est une faute morale ou une faiblesse. Pourtant, le jugement des autres n’explique pas une maladie et ne devrait pas déterminer l’accès aux soins.', array['La stigmatisation peut faire croire qu’une difficulté psychologique est une faute morale ou une faiblesse. Pourtant, le jugement des autres n’explique pas une maladie et ne devrait pas déterminer l’accès aux soins.']::text[], '[{"h":"Une situation du quotidien","p":["Une personne évite un centre de santé de peur d’être reconnue par des connaissances."]},{"h":"Un premier pas possible","p":["Cherchez des informations fiables, posez des questions sur la confidentialité et rappelez-vous que vous avez droit à une écoute digne. Les mots que nous utilisons pour parler des autres comptent."]},{"h":"Quand chercher du soutien ?","p":["Une consultation peut aider à comprendre les symptômes sans vous réduire à une étiquette."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['chez-nous-on-est-forts-quand-la-force-devient-un-silence','foi-priere-et-soutien-psychologique-faut-il-choisir','ne-raconte-pas-nos-problemes-le-poids-du-secret-familial']::text[], 1, 'gold', 'a_relire', false, null, 59, false, false),
  ('hommes-africains-et-pression-d-etre-le-pilier', 'Hommes africains et pression d’être le pilier', 'Culture, foi et société', 'Dans certains milieux, les hommes ressentent une forte attente de réussite, de protection et de stabilité financière. Cette pression peut rendre difficile l’expression de la peur ou de la tristesse. Les expériences individuelles restent très variées.', array['Dans certains milieux, les hommes ressentent une forte attente de réussite, de protection et de stabilité financière. Cette pression peut rendre difficile l’expression de la peur ou de la tristesse. Les expériences individuelles restent très variées.']::text[], '[{"h":"Une situation du quotidien","p":["Après une perte d’emploi, un père évite ses proches parce qu’il se sent jugé sur sa capacité à subvenir aux besoins de sa famille."]},{"h":"Un premier pas possible","p":["Proposez des conversations où la valeur d’une personne n’est pas mesurée uniquement à ses revenus. Demander de l’aide et partager les responsabilités ne retire rien à sa dignité."]},{"h":"Quand chercher du soutien ?","p":["Si le sommeil, l’humeur ou le fonctionnement se dégradent, une aide professionnelle est indiquée."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['chez-nous-on-est-forts-quand-la-force-devient-un-silence','foi-priere-et-soutien-psychologique-faut-il-choisir','ne-raconte-pas-nos-problemes-le-poids-du-secret-familial']::text[], 1, 'sage', 'a_relire', false, null, 60, false, false),
  ('reussir-a-tout-prix-quand-les-attentes-etouffent', 'Réussir à tout prix : quand les attentes étouffent', 'Culture, foi et société', 'La réussite scolaire, professionnelle ou familiale peut être une source de fierté. Mais lorsque l’estime de soi dépend entièrement des résultats ou du regard des autres, chaque difficulté peut sembler catastrophique.', array['La réussite scolaire, professionnelle ou familiale peut être une source de fierté. Mais lorsque l’estime de soi dépend entièrement des résultats ou du regard des autres, chaque difficulté peut sembler catastrophique.']::text[], '[{"h":"Une situation du quotidien","p":["Une jeune adulte se sent en échec parce que son parcours ne correspond pas au calendrier attendu par sa famille."]},{"h":"Un premier pas possible","p":["Demandez-vous : « Quelles valeurs sont vraiment les miennes ? » Définissez un objectif réaliste et distinguez votre valeur personnelle de votre performance."]},{"h":"Quand chercher du soutien ?","p":["Un accompagnement peut aider si la pression s’accompagne d’anxiété, d’épuisement ou d’une souffrance durable."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : https://www.afro.who.int/news/barriers-mental-health-care-africa','Faleti et Akinlotan, Stigmatisation of mental illness in Africa: a systematic review (2024/2025), DOI 10.1080/09638237.2024.2426982.','Nanji et Olivier, Providing Mental Healthcare through Faith-based Entities in Africa: A Systematic Review (2024).']::text[], array['chez-nous-on-est-forts-quand-la-force-devient-un-silence','foi-priere-et-soutien-psychologique-faut-il-choisir','ne-raconte-pas-nos-problemes-le-poids-du-secret-familial']::text[], 1, 'forest', 'a_relire', false, null, 61, false, false),
  ('parler-de-sante-mentale-en-famille-sans-declencher-une-dispute', 'Parler de santé mentale en famille sans déclencher une dispute', 'Culture, foi et société', 'Changer les représentations demande souvent du temps. Une conversation peut mieux commencer par une expérience concrète que par un débat sur qui a raison.', array['Changer les représentations demande souvent du temps. Une conversation peut mieux commencer par une expérience concrète que par un débat sur qui a raison.']::text[], '[{"h":"Une situation du quotidien","p":["Une fille souhaite expliquer à ses parents qu’elle consulte pour son anxiété, mais redoute leur réaction."]},{"h":"Un premier pas possible","p":["Choisissez un moment calme, parlez en « je », expliquez ce que vous vivez et ce que vous attendez : « J’aimerais être écoutée, pas forcément conseillée ». Vous pouvez garder certaines informations privées."]},{"h":"Quand chercher du soutien ?","p":["Si la conversation expose à la violence ou au contrôle, privilégiez votre sécurité et cherchez un soutien extérieur fiable."]}]'::jsonb, 'À retenir : vous n’avez pas à affronter seul(e) une difficulté qui prend trop de place dans votre vie.', array['Papworth et al., Low Intensity Cognitive Behaviour Therapy: A Practitioner’s Guide (2e éd., 2018).','Farrand (dir.), Low-Intensity CBT Skills and Interventions: A Practitioner’s Manual (2020 ; 2e éd. 2025).','Bennett-Levy et al., Oxford Guide to Low Intensity CBT Interventions (2010).','Richards et Whyte, Reach Out: National Programme Student Materials for Psychological Wellbeing Practitioners (3e éd., 2011).','Judith S. Beck, Cognitive Behavior Therapy: Basics and Beyond (3e éd., 2020).','Kennerley, Kirk et Westbrook, An Introduction to Cognitive Behaviour Therapy (3e éd., 2016).','Greenberger et Padesky, Mind Over Mood (2e éd., 2015).','OMS, Mental disorders, fiche d’information : https://www.who.int/news-room/fact-sheets/detail/mental-disorders','OMS Afrique, Barriers to mental health care in Africa : htt